import{c as a,S as o,h as d,l as r}from"./chunks/framework.CuiMOlaJ.js";const u=JSON.parse('{"title":"第一章 Hadoop 分布式大数据系统概述","description":"介绍分布式系统的基本概念，以及 Hadoop、HDFS、YARN、MapReduce、ZooKeeper、Hive 等核心组件在大数据平台中的定位。","frontmatter":{"title":"第一章 Hadoop 分布式大数据系统概述","description":"介绍分布式系统的基本概念，以及 Hadoop、HDFS、YARN、MapReduce、ZooKeeper、Hive 等核心组件在大数据平台中的定位。","categories":["Linux 分布式集群"],"outline":[2,3],"date":"2024-10-18T00:00:00.000Z","recommend":1,"tags":["运维","分布式","Linux","Hadoop"],"head":[["meta",{"name":"keywords","content":"Linux企业级运维, 分布式, Linux, 架构, Hadoop, 大数据"}]],"cover":"https://cdn.imufeng.cn/mblog/202411161444264.png"},"headers":[],"relativePath":"training/linux/hadoop-cluster/overview.md","filePath":"training/linux/hadoop-cluster/overview.md","lastUpdated":1774319582000}'),i={name:"training/linux/hadoop-cluster/overview.md"};function t(l,e,c,p,n,h){return o(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1729209600000"},[...e[0]||(e[0]=[r('<h1 id="第一章-hadoop-分布式大数据系统概述" tabindex="-1">第一章 Hadoop 分布式大数据系统概述 <a class="header-anchor" href="#第一章-hadoop-分布式大数据系统概述" aria-label="Permalink to &quot;第一章 Hadoop 分布式大数据系统概述&quot;">​</a></h1><h2 id="一、什么是分布式系统" tabindex="-1">一、什么是分布式系统 <a class="header-anchor" href="#一、什么是分布式系统" aria-label="Permalink to &quot;一、什么是分布式系统&quot;">​</a></h2><p>分布式系统是指将多个独立节点通过网络组织在一起，共同对外提供统一服务的一类系统架构。对于使用者而言，它像是一个整体；而在内部，数据存储、任务执行、状态同步和故障恢复则由多个节点协同完成。</p><p>分布式系统的核心价值主要体现在以下几个方面：</p><ul><li><strong>横向扩展：</strong> 当单机性能不足时，可以通过增加节点扩容。</li><li><strong>容错能力：</strong> 单个节点故障后，系统仍可继续提供部分或全部能力。</li><li><strong>资源共享：</strong> 多台服务器可以共同承担存储与计算任务。</li><li><strong>弹性调度：</strong> 任务可以在不同节点之间重新分配，提高整体利用率。</li></ul><p>与此同时，分布式系统也带来了网络延迟、数据一致性、节点选举、故障检测与恢复等复杂问题，因此往往需要一整套成熟的软件体系来支撑。</p><h2 id="二、hadoop-的定位" tabindex="-1">二、Hadoop 的定位 <a class="header-anchor" href="#二、hadoop-的定位" aria-label="Permalink to &quot;二、Hadoop 的定位&quot;">​</a></h2><p>Apache Hadoop 是 Apache 软件基金会维护的开源大数据基础平台，最早面向海量数据的分布式存储与离线计算场景。经过多年发展，Hadoop 已不只是单一组件，而是逐渐形成了一个完整生态。</p><p>日常讨论中的 “Hadoop” 可能有两层含义：</p><ol><li>狭义上，指 Hadoop 的核心框架，即 <code>HDFS + YARN + MapReduce</code>。</li><li>广义上，指围绕 Hadoop 发展起来的一整套大数据生态，包括 <code>ZooKeeper</code>、<code>Hive</code>、<code>HBase</code>、<code>Spark</code> 等工具。</li></ol><h2 id="三、hadoop-核心组件" tabindex="-1">三、Hadoop 核心组件 <a class="header-anchor" href="#三、hadoop-核心组件" aria-label="Permalink to &quot;三、Hadoop 核心组件&quot;">​</a></h2><h3 id="_3-1-hdfs" tabindex="-1">3.1 HDFS <a class="header-anchor" href="#_3-1-hdfs" aria-label="Permalink to &quot;3.1 HDFS&quot;">​</a></h3><p><code>HDFS</code>（Hadoop Distributed File System）是 Hadoop 的分布式文件系统，负责海量数据的分布式存储。它会将文件切分为多个数据块，并分散保存到不同节点上，同时通过副本机制提升可用性和容错能力。</p><p>在典型架构中：</p><ul><li><code>NameNode</code> 负责元数据管理，如目录结构、文件块映射、权限信息。</li><li><code>DataNode</code> 负责真实数据块的存储与读写。</li></ul><h3 id="_3-2-yarn" tabindex="-1">3.2 YARN <a class="header-anchor" href="#_3-2-yarn" aria-label="Permalink to &quot;3.2 YARN&quot;">​</a></h3><p><code>YARN</code>（Yet Another Resource Negotiator）是 Hadoop 的资源管理与任务调度平台，用来协调集群中的 CPU、内存等资源。</p><p>YARN 主要包含：</p><ul><li><code>ResourceManager</code>：统一管理集群资源。</li><li><code>NodeManager</code>：负责单个节点上的资源汇报与任务执行。</li><li><code>ApplicationMaster</code>：负责具体应用的任务协调。</li></ul><h3 id="_3-3-mapreduce" tabindex="-1">3.3 MapReduce <a class="header-anchor" href="#_3-3-mapreduce" aria-label="Permalink to &quot;3.3 MapReduce&quot;">​</a></h3><p><code>MapReduce</code> 是 Hadoop 早期最重要的分布式计算模型。它将任务拆分为 <code>Map</code> 与 <code>Reduce</code> 两个阶段，使海量数据可以并行处理。虽然现在很多场景会用 Spark 或 Flink 替代 MapReduce，但它依然有助于理解 Hadoop 生态中“存储与计算分离”的基础思想。</p><h2 id="四、常见配套组件" tabindex="-1">四、常见配套组件 <a class="header-anchor" href="#四、常见配套组件" aria-label="Permalink to &quot;四、常见配套组件&quot;">​</a></h2><h3 id="_4-1-zookeeper" tabindex="-1">4.1 ZooKeeper <a class="header-anchor" href="#_4-1-zookeeper" aria-label="Permalink to &quot;4.1 ZooKeeper&quot;">​</a></h3><p><code>ZooKeeper</code> 是分布式协调服务，主要用于配置管理、分布式锁、命名服务、Leader 选举等场景。在 Hadoop 生态中，许多组件会依赖 ZooKeeper 维持分布式状态一致性。</p><h3 id="_4-2-hive" tabindex="-1">4.2 Hive <a class="header-anchor" href="#_4-2-hive" aria-label="Permalink to &quot;4.2 Hive&quot;">​</a></h3><p><code>Hive</code> 是基于 Hadoop 的数据仓库工具，为结构化数据提供类 SQL 查询能力。用户可以使用 <code>HiveQL</code> 编写分析语句，底层再由 Hadoop 生态组件负责实际执行。</p><h3 id="_4-3-其他常见组件" tabindex="-1">4.3 其他常见组件 <a class="header-anchor" href="#_4-3-其他常见组件" aria-label="Permalink to &quot;4.3 其他常见组件&quot;">​</a></h3><p>围绕 Hadoop 还发展出许多常见项目，例如：</p><ul><li><code>HBase</code>：面向海量结构化数据的分布式列式数据库。</li><li><code>Spark</code>：通用分布式计算引擎，适合批处理、流处理和机器学习。</li><li><code>Sqoop</code>：用于传统数据库与 Hadoop 之间的数据导入导出。</li><li><code>Oozie</code>：工作流编排与任务调度工具。</li></ul><h2 id="五、为什么先学基础集群部署" tabindex="-1">五、为什么先学基础集群部署 <a class="header-anchor" href="#五、为什么先学基础集群部署" aria-label="Permalink to &quot;五、为什么先学基础集群部署&quot;">​</a></h2><p>在云平台与容器平台越来越成熟的今天，很多组件都可以直接通过镜像或托管服务一键部署。但手动搭建一套基础 Hadoop 集群仍然很有价值，因为它能够帮助我们理解：</p><ul><li>各组件的职责划分。</li><li>配置文件之间的依赖关系。</li><li>节点通信与端口规划。</li><li>数据、计算与协调服务之间的协作方式。</li></ul><p>本系列后续章节将从最基础的系统环境准备开始，逐步完成 Hadoop、ZooKeeper 和 Hive 的安装与配置。</p><h2 id="参考内容" tabindex="-1">参考内容 <a class="header-anchor" href="#参考内容" aria-label="Permalink to &quot;参考内容&quot;">​</a></h2><ul><li><a href="https://hadoop.apache.org/" target="_blank" rel="noreferrer">Apache Hadoop 官网</a></li><li><a href="https://www.atlassian.com/zh/microservices/microservices-architecture/distributed-architecture" target="_blank" rel="noreferrer">What is a distributed architecture? | Atlassian</a></li><li><a href="https://icyfenix.cn/" target="_blank" rel="noreferrer">凤凰架构</a></li></ul>',35)])])}const H=a(i,[["render",t]]);export{u as __pageData,H as default};
